run_generated_snippet: doors = revit_ro.get_elements("Doors")
# find door by Mark
door_id = None
for d in doors:
    m = revit_ro.get_param(d["id"], "Mark")
    if m == "zz-99":
        door_id = d["id"]
        door_name = d.get("name")
        break
if door_id == None:
    result = {"error": "Door with Mark zz-99 not found"}
else:
    def get_point(eid):
        g = revit_ro.get_geometry_bbox(eid)
        if g != None and "center" in g and g["center"] != None:
            return g["center"]
        line = revit_ro.get_line(eid)
        if line != None and "point" in line and line["point"] != None:
            return line["point"]
        # fallback None
        return None
    door_pt = get_point(door_id)
    if door_pt == None:
        result = {"error": "Geometry for door zz-99 is unavailable"}
    else:
        cols = revit_ro.get_elements("Columns")
        best = None
        # sqrt via Newton-Raphson
        def sqrt_nr(s):
            if s == 0:
                return 0.0
            x = s
            # make a better initial guess
            if x < 1.0:
                x = 1.0
            for i in range(20):
                x = 0.5 * (x + s / x)
            return x
        for c in cols:
            cp = get_point(c["id"])
            if cp == None:
                continue
            dx = cp[0] - door_pt[0]
            dy = cp[1] - door_pt[1]
            dz = cp[2] - door_pt[2]
            sd = dx*dx + dy*dy + dz*dz
            d = sqrt_nr(sd)
            if best == None or d < best["distance_m"]:
                best = {"column_id": c["id"], "column_name": c.get("name"), "distance_m": d}
        if best == None:
            result = {"error": "No columns with geometry available"}
        else:
            # round distance to 3 decimal places
            best["distance_m"] = round(best["distance_m"], 3)
            result = {"door_id": door_id, "door_name": door_name, "closest_column": best}
