run_generated_snippet: doors = revit_ro.get_elements("Doors")
count = 0
matching_ids = []
for d in doors:
    if revit_ro.get_param(d["id"], "Type Name") == "d1":
        host = revit_ro.get_host_id(d["id"])
        if host != None:
            if revit_ro.get_param(host, "Mark") == "w-01":
                count += 1
                matching_ids.append(d["id"])
result = {"count": count, "door_ids": matching_ids}

