room_id = 1680622
count = 0
door_ids = []
for d in doors:
    rel = revit_ro.get_relationship(d["id"], "rooms_bounding_door")
    if rel != None:
        if rel["from_room_id"] == room_id or rel["to_room_id"] == room_id:
            count += 1
            door_ids.append(d["id"])
